entries[161908] = { ["name"] = "Reins of the Dusky Waycrest Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Dusky Waycrest Gryphon.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Order of Embers\n- Exalted\nRequired achievement: Battle for Azeroth Pathfinder, Part Two\n\n\"Common to the dark forests of Drustvar, these gryphon are silent and swift. Their prowess at operating on their own or as mounts lends them to be used for ambush and shock tactics.\"\nVendor:\nQuartermaster Alcorn\nZone:\nDrustvar\nFaction:\nOrder of Embers - Exalted\nCost:" }
entries[161909] = { ["name"] = "Reins of the Stormsong Coastwatcher", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Stormsong Coastwatcher.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Storm's Wake\n- Exalted\nRequired achievement: Battle for Azeroth Pathfinder, Part Two\n\n\"Tasked with keeping watch on the seas for approaching dangers, the Stormsong Coastwatchers fly constant patrols.\"\nVendor:\nSister Lilyana\nZone:\nStormsong Valley\nFaction:\nStorm's Wake - Exalted\nCost:" }
entries[161910] = { ["name"] = "Reins of the Smoky Charger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Smoky Charger.\nSummons and dismisses your Waycrest Smoky Black Charger.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Order of Embers\n- Exalted\n\n\"Among the oldest horse breeds in Kul Tiras, they even led many a charge in the original struggle with the drust.\"\nVendor:\nQuartermaster Alcorn\nZone:\nDrustvar\nFaction:\nOrder of Embers - Exalted\nCost:" }
entries[161911] = { ["name"] = "Reins of the Admiralty Stallion", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon an Admiralty Stallion.\nSummons and dismisses your Admiralty Stallion.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Proudmoore Admiralty\n- Exalted\n\n\"These sleek white stallions are the few mounts allowed to embark on Kul Tiran ships.\"\nVendor:\nProvisioner Fray\nZone:\nTiragarde Sound\nFaction:\nProudmoore Admiralty - Exalted\nCost:" }
