entries[162121] = { ["name"] = "Vantus Rune Technique: Uldir", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Uldir.\nCraft a Vantus Rune: Uldir.\nRequires Kul Tiran Inscription (100)\nSell Price:\nVantus Rune: Uldir\nUse: Attune yourself to the energies of the targeted Uldir raid boss, increasing your Versatility by 2078 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Light Parchment , Crimson Ink (20), Viridescent Ink (10)" }
entries[162122] = { ["name"] = "Amber Rallying Horn", ["text"] = "Champion Equipment\nBinds when used\nUse: Equip a champion with an Amber Rallying Horn which grants:Increases success chance of missions by 10% for each accompanying troop.\nSell Price:" }
entries[162123] = { ["name"] = "Mission Report", ["text"] = "Quest Item\n\"The report contains details of the mission to capture Hillcrest Pasture in Stormsong Valley.\"" }
entries[162124] = { ["name"] = "Vantus Rune Technique: Uldir", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Uldir more efficiently.\nReduces the materials required to craft a Vantus Rune: Uldir.\nRequires Kul Tiran Inscription (100)\nSell Price:\nVantus Rune: Uldir\nUse: Attune yourself to the energies of the targeted Uldir raid boss, increasing your Versatility by 2078 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Light Parchment , Crimson Ink (18), Viridescent Ink (8)" }
entries[162125] = { ["name"] = "Vantus Rune Technique: Uldir", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Uldir more efficiently.\nGreatly reduces the materials required to craft a Vantus Rune: Uldir.\nRequires Kul Tiran Inscription (100)\nSell Price:\nVantus Rune: Uldir\nUse: Attune yourself to the energies of the targeted Uldir raid boss, increasing your Versatility by 2078 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Light Parchment , Crimson Ink (15), Viridescent Ink (6)" }
