entries[162127] = { ["name"] = "River Clam Pearl", ["text"] = "Binds when picked up\nUnique\nUse: Grants water breathing and increases sea floor movement speed by 100% while in Nazmir.\n1 Charge\nSell Price:" }
entries[162128] = { ["name"] = "Recipe: Steelskin Potion", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Steelskin Potion more effectively.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (1)\nRequires7th Legion\n- Revered\nSell Price:\nSteelskin Potion\nUse: Infuses your body with resilient energy, increasing your Armor by 269 for 25 sec. (5 Min Cooldown)\nSell Price:\nRequires Sea Stalk (10), Riverbud (8), Crystal Vial" }
entries[162129] = { ["name"] = "Recipe: Potion of Replenishment", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Potion of Replenishment more effectively.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (1)\nRequires Storm's Wake\n- Revered\nSell Price:\nPotion of Replenishment\nUse: Puts the imbiber in an elevated state of focus where they can restore up to ( 601 * 10) mana over 10 sec, but they are defenseless until their focus is broken. (5 Min Cooldown)\nSell Price:\nRequires Siren's Pollen (10), Star Moss (8), Crystal Vial" }
entries[162130] = { ["name"] = "Recipe: Potion of Bursting Blood", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Potion of Bursting Blood more effectively.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (1)\nRequires Proudmoore Admiralty\n- Revered\nSell Price:\nPotion of Bursting Blood\nUse: Imbues your blood with heat for 25 sec, giving your melee attacks a chance to create a burst of blood, dealing 5371 Physical damage split evenly amongst all nearby enemies. (5 Min Cooldown)\nSell Price:\nRequires Siren's Pollen (8), Riverbud (6), Crystal Vial" }
entries[162131] = { ["name"] = "Recipe: Potion of Rising Death", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Potion of Rising Death more effectively.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (1)\nRequires Order of Embers\n- Revered\nSell Price:\nPotion of Rising Death\nUse: Empowers you with shadow magic for 25 sec, giving your damaging ranged abilities a chance to send out a death bolt that grows in intensity as it travels, dealing up to 331209 Shadow damage. (5 Min Cooldown)\nSell Price:\nRequires Sea Stalk (8), Star Moss (6), Crystal Vial" }
entries[162132] = { ["name"] = "Recipe: Flask of the Currents", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Flask of the Currents more effectively.\nChance to create multiple flasks.\nRequires Kul Tiran Alchemy (1)\nRequires7th Legion\n- Revered\nSell Price:\nFlask of the Currents\nUse: Increases Agility by 71 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Anchor Weed (5), Akunda's Bite (10), Sea Stalk (15), Crystal Vial" }
entries[162133] = { ["name"] = "Recipe: Flask of Endless Fathoms", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Flask of Endless Fathoms more effectively.\nChance to create multiple flasks.\nRequires Kul Tiran Alchemy (1)\nRequires Storm's Wake\n- Revered\nSell Price:\nFlask of Endless Fathoms\nUse: Increases Intellect by 71 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Anchor Weed (5), Winter's Kiss (10), Riverbud (15), Crystal Vial" }
entries[162134] = { ["name"] = "Recipe: Flask of the Vast Horizon", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Flask of the Vast Horizons more effectively.\nChance to create multiple flasks.\nRequires Kul Tiran Alchemy (1)\nRequires Proudmoore Admiralty\n- Revered\nSell Price:\nFlask of the Vast Horizon\nUse: Increases Stamina by 107 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Anchor Weed (5), Winter's Kiss (10), Star Moss (15), Crystal Vial" }
entries[162135] = { ["name"] = "Recipe: Flask of the Undertow", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Flask of the Undertow more effectively.\nChance to create multiple flasks.\nRequires Kul Tiran Alchemy (1)\nRequires Order of Embers\n- Revered\nSell Price:\nFlask of the Undertow\nUse: Increases Strength by 71 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Anchor Weed (5), Akunda's Bite (10), Siren's Pollen (15), Crystal Vial" }
entries[162136] = { ["name"] = "Recipe: Endless Tincture of Renewed Combat", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Endless Tincture of Renewed Combat more efficiently.\nChance to create multiple tinctures.\nRequires Kul Tiran Alchemy (1)\nRequires Tortollan Seekers\n- Revered\nSell Price:\nEndless Tincture of Renewed Combat\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 9 Versatility\nEquip: Restores 696 health whenever you kill a target that yields experience or honor.\nSell Price:\nRequires Siren's Pollen (18), Riverbud (18), Expulsom , Crystal Vial\nOptional Reagents: Optional Reagent Slot (#47)" }
entries[162137] = { ["name"] = "Recipe: Siren's Alchemist Stone", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Siren's Alchemist Stone more efficiently.\nFurther reduces the materials required to craft a Siren's Alchemist Stone.\nRequires Kul Tiran Alchemy (1)\nRequires Tortollan Seekers\n- Revered\nSell Price:\nSiren's Alchemist Stone\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 9 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 23 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Kul Tiran Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:\nRequires Sea Stalk (16), Star Moss (16), Expulsom\nOptional Reagents: Optional Reagent Slot (#47)" }
entries[162138] = { ["name"] = "Recipe: Endless Tincture of Fractional Power", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Endless Tincture of Fractional Power more efficiently.\nChance to create multiple tinctures.\nRequires Kul Tiran Alchemy (1)\nRequires7th Legion\n- Revered\nSell Price:\nEndless Tincture of Fractional Power\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 9 Versatility\nUse: Copies the wearer's current flask buff but at a fraction of the power. Lasts 12 sec. (1 Min Cooldown)\nSell Price:\nRequires Flask of the Currents , Flask of Endless Fathoms , Flask of the Vast Horizon , Flask of the Undertow , Expulsom (6)" }
entries[162139] = { ["name"] = "Recipe: Surging Alchemist Stone", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Surging Alchemist Stone more efficiently.\nFurther reduces the materials required to craft a Surging Alchemist Stone.\nRequires Kul Tiran Alchemy (1)\nRequires7th Legion\n- Revered\nSell Price:\nSurging Alchemist Stone\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 9 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 24 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Kul Tiran Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:\nRequires Anchor Weed (12), Akunda's Bite (32), Winter's Kiss (32), Expulsom (16)" }
