entries[162259] = { ["name"] = "Recipe: Sea Mist Potion", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Sea Mist Potion more efficiently.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (1)\nSell Price:\nSea Mist Potion\nUse: Turns the imbiber into a cloud, allowing them to fall slowly from great heights and float over water surfaces. Lasts 1 min. (5 Min Cooldown)\nSell Price:\nRequires Sea Stalk (10), Crystal Vial" }
