entries[162339] = { ["name"] = "Schematic: XA-1000 Surface Skimmer", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an XA-1000 Surface Skimmer more efficiently.\nGreatly reduces the materials required to craft an XA-1000 Surface Skimmer.\nRequires Kul Tiran Engineering (1)\nSell Price:\nXA-1000 Surface Skimmer\nUse: Deploy a boat which will immediately begin moving across the water for 25 sec. Does not work on land. (30 Sec Cooldown)\nSell Price:\nRequires Monelite Ore (10), Storm Silver Ore (5), Insulated Wiring (4)" }
entries[162340] = { ["name"] = "Schematic: Electroshock Mount Motivator", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Electroshock Mount Motivator more efficiently.\nGreatly reduces the materials required to craft an Electroshock Mount Motivator.\nRequires Kul Tiran Engineering (1)\nSell Price:\nElectroshock Mount Motivator\nUse: Increases mounted movement speed by 10% for 10 sec. Stacks up to 5 times. Increased motivation may cause your mount to become disoriented.\n\nDoes not stack with other bonuses to mounted speed.\n50 Charges\n\"Some animals were harmed in the design of this device. But they're better now... mostly.\"\nSell Price:\nRequires Monelite Ore (8), Storm Silver Ore (4), Insulated Wiring (6)" }
entries[162341] = { ["name"] = "Schematic: Interdimensional Companion Repository", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Interdimensional Companion Repository more efficiently.\nGreatly reduces the materials required to craft an Interdimensional Companion Repository.\nRequires Kul Tiran Engineering (1)\nRequires Storm's Wake\n- Revered\nSell Price:\nInterdimensional Companion Repository\nUse: Summons a portable stable master that will allow hunters to interact with it for up to 2 min.\nSell Price:\nRequires Monelite Ore (5), Storm Silver Ore (4), Insulated Wiring (5)" }
entries[162342] = { ["name"] = "Schematic: Deployable Attire Rearranger", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Deployable Attire Rearranger more efficiently.\nGreatly reduces the materials required to craft a Deployable Attire Rearranger.\nRequires Kul Tiran Engineering (1)\nRequires Storm's Wake\n- Revered\nSell Price:\nDeployable Attire Rearranger\nUse: Summons a device that will allow you to alter the look of your armor. Device lasts for up to 2 min.\n\"Disclaimer: Due to the functionality of this product, slight headaches, nausea and race and/or gender changes have been known to occur. Use with caution.\"\nSell Price:\nRequires Monelite Ore (5), Storm Silver Ore (4), Insulated Wiring (5)" }
entries[162343] = { ["name"] = "Schematic: Crow's Nest Scope", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Crow's Nest Scope more efficiently.\nGreatly reduces the materials required to craft a Crow's Nest Scope.\nRequires Kul Tiran Engineering (1)\nSell Price:\nCrow's Nest Scope\nUse: Permanently attaches a scope to a ranged weapon, sometimes increasing Critical Strike by 194 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound.\nSell Price:\nRequires Monelite Ore (10), Storm Silver Ore (5)" }
