entries[162443] = { ["name"] = "Pattern: Battle Flag: Spirit of Freedom", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Battle Flag: Spirit of Freedom more efficiently.\nGreatly reduces the materials required to craft a Battle Flag: Spirit of Freedom.\nRequires Kul Tiran Tailoring (1)\nSell Price:\nBattle Flag: Spirit of Freedom\nUse: Drop a flag onto the battlefield that decreases the amount of time one is affected by crowd controlling effects for all allies within 15 yards of its location. Lasts 30 sec.\n\nOnly usable on Kul Tiras, Zandalar and in unrated Battlegrounds. (5 Min Cooldown)\nRequires Tidespray Linen (8), Embroidered Deep Sea Satin (5), Nylon Thread (16)" }
entries[162444] = { ["name"] = "Pattern: Battle Flag: Phalanx Defense", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Battle Flag: Phalanx Defense more efficiently.\nGreatly reduces the materials required to craft a Battle Flag: Phalanx Defense.\nRequires Kul Tiran Tailoring (1)\nSell Price:\nBattle Flag: Phalanx Defense\nUse: Drop a flag onto the battlefield that decreases damage taken by 15% for all allies within 15 yards of its location. Lasts 30 sec.\n\nOnly usable on Kul Tiras, Zandalar and in unrated Battlegrounds. (5 Min Cooldown)\nRequires Tidespray Linen (8), Embroidered Deep Sea Satin (5), Nylon Thread (16)" }
entries[162445] = { ["name"] = "Pattern: Battle Flag: Rallying Swiftness", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Battle Flag: Rallying Swiftness more efficiently.\nGreatly reduces the materials required to craft a Battle Flag: Rallying Swiftness.\nRequires Kul Tiran Tailoring (1)\nSell Price:\nBattle Flag: Rallying Swiftness\nUse: Bear a battle flag on your back, increasing you and your party's mounted speed within 10 yards by 15% for 15 sec.\n\nOnly usable while mounted.\n\nOnly usable on Kul Tiras, Zandalar and in unrated Battlegrounds. (5 Min Cooldown)\nRequires Tidespray Linen (8), Embroidered Deep Sea Satin (5), Nylon Thread (16)" }
