entries[162623] = { ["name"] = "Tome of Hex: Zandalari Tendonripper", ["text"] = "Binds when picked up\nClasses: Shaman\nUse: Teaches Hex: Zandalari Tendonripper.\nTransforms the enemy into a Zandalari Tendonripper for 1 min. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.\nRequires Zandalari Empire\n- Revered\nSell Price:" }
entries[162624] = { ["name"] = "Tome of Hex: Wicker Mongrel", ["text"] = "Binds when picked up\nClasses: Shaman\nUse: Teaches Hex: Wicker Mongrel.\nTransforms the enemy into a wicker mongrel for 1 min. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.\nRequires Order of Embers\n- Revered\nSell Price:" }
entries[162625] = { ["name"] = "Tome of Polymorph: Direhorn", ["text"] = "Binds when picked up\nClasses: Mage\nUse: Teaches Polymorph: Direhorn\nTransforms the enemy into a baby direhorn, wandering around incapacitated for 1 min. While affected, the victim cannot take actions but will regenerate health very quickly. Damage will cancel the effect. Limit 1.\n\nOnly works on Beasts, Humanoids and Critters. [ Glyph of Crittermorph : When critters are affected, can affect multiple targets, and has a duration of 1 day ]\nRequires Zandalari Empire\n- Revered\nSell Price:" }
entries[162626] = { ["name"] = "Tome of Polymorph: Bumblebee", ["text"] = "Binds when picked up\nClasses: Mage\nUse: Teaches Polymorph: Bumblebee\nTransforms the enemy into a bumblebee, wandering around incapacitated for 1 min. While affected, the victim cannot take actions but will regenerate health very quickly. Damage will cancel the effect. Limit 1.\n\nOnly works on Beasts, Humanoids and Critters. [ Glyph of Crittermorph : When critters are affected, can affect multiple targets, and has a duration of 1 day ]\nRequires Storm's Wake\n- Revered\nSell Price:" }
