entries[162691] = { ["name"] = "Recipe: Steelskin Potion", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Steelskin Potion more effectively.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (1)\nRequires The Honorbound\n- Revered\nSell Price:\nSteelskin Potion\nUse: Infuses your body with resilient energy, increasing your Armor by 269 for 25 sec. (5 Min Cooldown)\nSell Price:\nRequires Sea Stalk (10), Riverbud (8), Crystal Vial" }
entries[162692] = { ["name"] = "Recipe: Potion of Replenishment", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Potion of Replenishment more effectively.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (1)\nRequires Zandalari Empire\n- Revered\nSell Price:\nPotion of Replenishment\nUse: Puts the imbiber in an elevated state of focus where they can restore up to ( 601 * 10) mana over 10 sec, but they are defenseless until their focus is broken. (5 Min Cooldown)\nSell Price:\nRequires Siren's Pollen (10), Star Moss (8), Crystal Vial" }
entries[162693] = { ["name"] = "Recipe: Potion of Bursting Blood", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Potion of Bursting Blood more effectively.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (1)\nRequires Talanji's Expedition\n- Revered\nSell Price:\nPotion of Bursting Blood\nUse: Imbues your blood with heat for 25 sec, giving your melee attacks a chance to create a burst of blood, dealing 5371 Physical damage split evenly amongst all nearby enemies. (5 Min Cooldown)\nSell Price:\nRequires Siren's Pollen (8), Riverbud (6), Crystal Vial" }
entries[162694] = { ["name"] = "Recipe: Potion of Rising Death", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Potion of Rising Death more effectively.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (1)\nRequires Voldunai\n- Revered\nSell Price:\nPotion of Rising Death\nUse: Empowers you with shadow magic for 25 sec, giving your damaging ranged abilities a chance to send out a death bolt that grows in intensity as it travels, dealing up to 331209 Shadow damage. (5 Min Cooldown)\nSell Price:\nRequires Sea Stalk (8), Star Moss (6), Crystal Vial" }
entries[162695] = { ["name"] = "Recipe: Flask of the Currents", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Flask of the Currents more effectively.\nChance to create multiple flasks.\nRequires Kul Tiran Alchemy (1)\nRequires The Honorbound\n- Revered\nSell Price:\nFlask of the Currents\nUse: Increases Agility by 71 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Anchor Weed (5), Akunda's Bite (10), Sea Stalk (15), Crystal Vial" }
