entries[162701] = { ["name"] = "Recipe: Endless Tincture of Fractional Power", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Endless Tincture of Fractional Power more efficiently.\nChance to create multiple tinctures.\nRequires Kul Tiran Alchemy (1)\nRequires The Honorbound\n- Revered\nSell Price:\nEndless Tincture of Fractional Power\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 9 Versatility\nUse: Copies the wearer's current flask buff but at a fraction of the power. Lasts 12 sec. (1 Min Cooldown)\nSell Price:\nRequires Flask of the Currents , Flask of Endless Fathoms , Flask of the Vast Horizon , Flask of the Undertow , Expulsom (6)" }
entries[162702] = { ["name"] = "Recipe: Surging Alchemist Stone", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Surging Alchemist Stone more efficiently.\nFurther reduces the materials required to craft a Surging Alchemist Stone.\nRequires Kul Tiran Alchemy (1)\nRequires The Honorbound\n- Revered\nSell Price:\nSurging Alchemist Stone\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 9 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 24 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Kul Tiran Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:\nRequires Anchor Weed (12), Akunda's Bite (32), Winter's Kiss (32), Expulsom (16)" }
