entries[162720] = { ["name"] = "Formula: Enchanter's Sorcerous Scepter", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Enchanter's Sorcerous Scepter more efficiently.\nGreatly reduces the materials required to create an Enchanter's Sorcerous Scepter.\nRequires Kul Tiran Enchanting (1)\nRequires The Honorbound\n- Revered\nSell Price:\nHorde\nEnchanter's Sorcerous Scepter\nBinds when equipped\nRanged Wand\n2 - 4 Nature Damage Speed 2.00\n(1.5 damage per second)\n+18 Intellect\n+5 Stamina\nDurability 110 / 110\nSell Price:\nAlliance\nEnchanter's Sorcerous Scepter\nBinds when equipped\nRanged Wand\n2 - 4 Shadow Damage Speed 2.00\n(1.5 damage per second)\n+18 Intellect\n+5 Stamina\nDurability 110 / 110\nSell Price:\nRequires Star Wood , Umbra Shard (6), Expulsom\nOptional Reagents: Optional Reagent Slot (#47)" }
entries[162721] = { ["name"] = "Formula: Enchant Weapon - Stalwart Navigation", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to enchant Stalwart Navigation more efficiently.\nPermanently enchant a weapon to sometimes increase Armor by 1 for 30 sec, stacking up to 5 times. Upon reaching 5 stacks, all stacks are consumed to grant you 9 Armor for 10 sec.\n\nGreatly reduced materials.\nRequires Kul Tiran Enchanting (1)\nRequires Zandalari Empire\n- Revered\nSell Price:" }
